(()=>{const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=v=>'₹'+Number(v).toLocaleString('en-IN');const labels={rental_received:'Rental received',rental_refunded:'Rental refunded',deposit_received:'Deposit received',deposit_refunded:'Deposit refunded'},methods={cash:'Cash',upi:'UPI',bank:'Bank transfer',card:'Card',other:'Other'};
window.GoRidePayments={render(b,owner=false){const records=b.payments||[];if(b.quoted_total==null&&!records.length)return '';let quote={};try{quote=JSON.parse(b.quote_details||'{}');}catch{}const net=prefix=>records.reduce((sum,p)=>sum+(p.kind===prefix+'_received'?p.amount:p.kind===prefix+'_refunded'?-p.amount:0),0),rental=net('rental'),deposit=net('deposit'),active=['confirmed','completed'].includes(b.status);const stats=[['Rental recorded',money(rental)],['Rental balance',active?money(Math.max(0,(b.quoted_total||0)-rental)):'Contact GoRide'],['Deposit held',money(deposit)],['Agreed deposit',Number.isSafeInteger(quote.deposit)?money(quote.deposit):'Not specified']];return `<section class="payment-panel" aria-label="Payments and deposit"><div class="payment-heading"><h3>Payments &amp; deposit</h3><span>Owner-recorded</span></div><dl class="payment-summary">${stats.map(([label,value])=>`<div><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl><p class="payment-help">These are records of payments arranged directly with GoRide. No money is collected or refunded by this screen.${active?'':' Any cancellation charges or refund due must be agreed separately.'}</p>${records.length?`<div class="payment-history">${records.map(p=>`<article><div><strong>${esc(labels[p.kind]||p.kind)} · ${money(p.amount)}</strong><time>${esc(new Date(p.created_at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'}))} IST</time></div><p>${esc(methods[p.method]||p.method)}${p.reference?' · Reference '+esc(p.reference):''}</p><p>${esc(p.note)}</p></article>`).join('')}</div>`:'<p class="payment-help">No payments recorded yet.</p>'}${owner&&b.quoted_total!=null?`<button type="button" class="secondary" data-record-payment="${esc(b.id)}">Record payment / refund</button>`:''}</section>`;}};
})();
